import React, {useEffect,useState} from 'react';
import {Link,useSearchParams} from 'react-router-dom';
import Navigation from '../../Components/Navigation';
import Footer from '../../Components/Footer';
import {blogApi,categoryName,Post} from '../../blog/api';
import '../../blog/blog.css';
export default function Blog(){
    
      useEffect(() => {
        window.scrollTo(0, 0);
      }, []);
    const [params,setParams]=useSearchParams();const category=params.get('category')||'';const page=Math.max(1,parseInt(params.get('page')||'1',10)||1);const [posts,setPosts]=useState<Post[]>([]);const [total,setTotal]=useState(0);const [error,setError]=useState('');const [loading,setLoading]=useState(true);
 useEffect(()=>{let live=true;setLoading(true);blogApi.publicPosts(category,page).then(r=>{if(live){setPosts(r.posts);setTotal(r.total)}}).catch(e=>{if(live)setError(e.message)}).finally(()=>{if(live)setLoading(false)});return()=>{live=false}},[category,page]);
 const choose=(c:string,p=1)=>setParams(c?{category:c,page:String(p)}:{page:String(p)});
 return <><Navigation/><main className="btr-blog"><header className="btr-blog-hero"><div className="btr-blog-container"><span className="btr-blog-eyebrow">BTR POLYMERS</span><h1>Industry insights.<br/><span>Building BTR.</span></h1><p>Perspectives from the plastics recycling industry and a firsthand look at building BTR Polymers.</p></div></header><section className="btr-blog-container btr-blog-list"><div className="btr-blog-section-intro"><span className="btr-blog-eyebrow">THE BTR JOURNAL</span><h2>Latest stories<span>.</span></h2><p>Industry knowledge, practical ideas, and updates from the team.</p></div><div className="btr-blog-filters">{[['','All articles'],['industry-insights','Industry Insights'],['building-btr','Building BTR']].map(([value,label])=><button key={value} className={category===value?'active':''} onClick={()=>choose(value)}>{label}</button>)}</div>{error&&<p role="alert">{error}</p>}{loading?<p>Loading articles...</p>:posts.length===0?<p>No published articles yet.</p>:<div className="btr-blog-cards">{posts.map(p=><Link className="btr-blog-card" to={`/blog/${p.slug}`} key={p.id}>{p.featured_image&&<img src={p.featured_image} alt="" loading="lazy"/>}<div className="btr-blog-card-body"><span className="btr-blog-eyebrow">{categoryName(p.category)}</span><h2>{p.title}</h2><p>{p.excerpt}</p><small>{p.published_at?new Date(p.published_at).toLocaleDateString():''}</small></div></Link>)}</div>}<div className="btr-blog-pagination">{page>1&&<button onClick={()=>choose(category,page-1)}>Previous</button>}{total>page*12&&<button onClick={()=>choose(category,page+1)}>Next</button>}</div></section></main><Footer/></>}
